import { useDroppable } from "@dnd-kit/core";

import { cn } from "../../lib/cn";
import type { GroupEdgeDropData, PaneEdgeDropData, TabDropEdge } from "./tabDragTypes";

type SplitEdgeDropData = GroupEdgeDropData | PaneEdgeDropData;

type SplitEdgeDropZoneProps = {
  id: string;
  data: SplitEdgeDropData;
  edge: TabDropEdge;
  testId: string;
  groupId?: string;
  tabId?: string;
  leafId?: string;
};

/**
 * Shared split-edge target used by both tab drags and pane-handle drags.
 * Drag source only changes the command resolved after drop; target geometry and
 * visual feedback intentionally follow the same tab-drag contract.
 */
export function SplitEdgeDropZone({
  id,
  data,
  edge,
  testId,
  groupId,
  tabId,
  leafId,
}: SplitEdgeDropZoneProps) {
  const { setNodeRef, isOver } = useDroppable({ id, data });

  return (
    <div
      ref={setNodeRef}
      aria-hidden="true"
      data-testid={testId}
      data-split-edge-drop-zone="true"
      data-dnd-type={data.type}
      data-drop-edge={edge}
      data-drop-group-id={groupId}
      data-tab-id={tabId}
      data-leaf-id={leafId}
      className={cn(
        "pointer-events-none absolute z-40 transition-colors",
        edgeHitTargetClass(edge),
        isOver && "border-2 border-primary bg-primary/20 backdrop-blur-[1px]",
      )}
    >
      {isOver ? (
        <span
          data-testid="split-edge-drop-feedback"
          className="absolute bottom-2 left-2 rounded-sm bg-background/80 px-1.5 py-0.5 text-[10px] font-medium text-foreground shadow-sm"
        >
          New split
        </span>
      ) : null}
    </div>
  );
}

export function edgeHitTargetClass(edge: TabDropEdge): string {
  switch (edge) {
    case "left":
      return "inset-y-0 left-0 w-[20%]";
    case "right":
      return "inset-y-0 right-0 w-[20%]";
    case "top":
      return "left-[20%] right-[20%] top-0 h-[20%]";
    case "bottom":
      return "bottom-0 left-[20%] right-[20%] h-[20%]";
  }
}

import type { TabDropEdge } from "./tabDragTypes";
import { SplitEdgeDropZone } from "./SplitEdgeDropZone";

const EDGES: TabDropEdge[] = ["left", "right", "top", "bottom"];

type PaneEdgeDropZonesProps = {
  tabId: string;
  leafId: string;
};

export function PaneEdgeDropZones({ tabId, leafId }: PaneEdgeDropZonesProps) {
  return (
    <>
      {EDGES.map((edge) => (
        <SplitEdgeDropZone
          key={edge}
          id={`pane-edge:${tabId}:${leafId}:${edge}`}
          data={{ type: "pane-edge", tabId, leafId, edge }}
          edge={edge}
          testId="pane-edge-drop-zone"
          tabId={tabId}
          leafId={leafId}
        />
      ))}
    </>
  );
}

import { useDroppable } from "@dnd-kit/core";
import type { ReactNode } from "react";

import { cn } from "../../lib/cn";
import type { TabDropEdge } from "./tabDragTypes";

type TabGroupDropSurfaceProps = {
  groupId: string;
  children: ReactNode;
};

export function TabGroupDropSurface({ groupId, children }: TabGroupDropSurfaceProps) {
  const body = useDroppable({
    id: `group-body:${groupId}`,
    data: { type: "group-body", groupId },
  });

  return (
    <div
      ref={body.setNodeRef}
      data-tab-group-body-id={groupId}
      data-dnd-type="group-body"
      className="relative min-h-0 flex-1 overflow-hidden bg-terminal"
    >
      {children}
      <TabGroupEdgeDropZone groupId={groupId} edge="left" />
      <TabGroupEdgeDropZone groupId={groupId} edge="right" />
      <TabGroupEdgeDropZone groupId={groupId} edge="top" />
      <TabGroupEdgeDropZone groupId={groupId} edge="bottom" />
    </div>
  );
}

function TabGroupEdgeDropZone({ groupId, edge }: { groupId: string; edge: TabDropEdge }) {
  const { setNodeRef, isOver } = useDroppable({
    id: `group-edge:${groupId}:${edge}`,
    data: { type: "group-edge", groupId, edge },
  });

  return (
    <div
      ref={setNodeRef}
      aria-hidden="true"
      data-testid="tab-group-edge-drop-zone"
      data-drop-edge={edge}
      data-drop-group-id={groupId}
      data-dnd-type="group-edge"
      className={cn(
        "pointer-events-none absolute z-40 transition-colors",
        edge === "left" && "inset-y-0 left-0 w-[20%]",
        edge === "right" && "inset-y-0 right-0 w-[20%]",
        edge === "top" && "left-[20%] right-[20%] top-0 h-[20%]",
        edge === "bottom" && "bottom-0 left-[20%] right-[20%] h-[20%]",
        isOver && "border-2 border-primary bg-primary/20 backdrop-blur-[1px]",
      )}
    >
      {isOver ? (
        <span className="absolute bottom-2 left-2 rounded-sm bg-background/80 px-1.5 py-0.5 text-[10px] font-medium text-foreground shadow-sm">
          New split
        </span>
      ) : null}
    </div>
  );
}

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { Globe, Pin, TerminalSquare, X } from "lucide-react";
import { memo, useMemo, type KeyboardEvent, type MouseEvent, type PointerEvent } from "react";

import { resolveActivityIndicator, type ActivitySummary } from "../../lib/activity";
import { cn } from "../../lib/cn";
import type { WorkspaceTab } from "../../lib/types";
import { StatusDot } from "../ui/StatusDot";

type SortableTabProps = {
  tab: WorkspaceTab;
  groupId: string;
  index: number;
  active: boolean;
  unread: boolean;
  activity?: ActivitySummary;
  isRenaming: boolean;
  renameValue: string;
  onRenameValueChange: (value: string) => void;
  onCommitRename: (tabId: string) => void;
  onCancelRename: () => void;
  onActivate: (tabId: string) => void;
  onClose: (tabId: string) => void;
  onContextMenu: (event: MouseEvent, tab: WorkspaceTab) => void;
};

export const SortableTab = memo(function SortableTab({
  tab,
  groupId,
  index,
  active,
  unread,
  activity,
  isRenaming,
  renameValue,
  onRenameValueChange,
  onCommitRename,
  onCancelRename,
  onActivate,
  onClose,
  onContextMenu,
}: SortableTabProps) {
  const sortableData = useMemo(
    () => ({ type: "tab", tabId: tab.id, groupId, index }),
    [tab.id, groupId, index],
  );
  const sortable = useSortable({
    id: `tab:${tab.id}`,
    disabled: isRenaming,
    data: sortableData,
  });
  const resolvedActivity = tab.kind === "browser" ? null : resolveActivityIndicator(activity);
  const activityIndicator = unread && (resolvedActivity === null || resolvedActivity === "done") ? "unread" : resolvedActivity;
  const isPinned = Boolean(tab.pinned);

  const style = {
    transform: CSS.Transform.toString(sortable.transform),
    transition: sortable.transition,
  };

  const stopPointer = (event: PointerEvent) => event.stopPropagation();

  return (
    <div
      ref={sortable.setNodeRef}
      {...sortable.attributes}
      {...sortable.listeners}
      role="tab"
      aria-selected={active}
      tabIndex={active ? 0 : -1}
      data-tab-dnd-id={tab.id}
      data-tab-group-id={groupId}
      data-tab-index={index}
      data-dnd-type="tab"
      draggable={false}
      onContextMenu={(event) => onContextMenu(event, tab)}
      onClick={() => onActivate(tab.id)}
      onKeyDown={(event: KeyboardEvent) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          onActivate(tab.id);
        }
      }}
      style={style}
      className={cn(
        "no-drag group relative flex min-w-tab max-w-tab cursor-pointer touch-none items-center gap-1.5 border-r border-border px-2 text-[12px] transition-colors outline-none focus-visible:ring-1 focus-visible:ring-inset focus-visible:ring-ring",
        active ? "bg-accent text-foreground" : "bg-card text-muted-foreground hover:bg-accent/45 hover:text-foreground",
        sortable.isDragging && "z-40 opacity-30",
      )}
    >
      {tab.kind === "browser" ? (
        <Globe className="size-3 shrink-0 text-primary" />
      ) : activityIndicator ? (
        <span
          data-testid={activityIndicator === "unread" ? "tab-unread-dot" : `tab-${activityIndicator}-indicator`}
          aria-label={`Agent ${activityIndicator}`}
          className="inline-flex size-3 shrink-0 items-center justify-center"
        >
          <StatusDot state={activityIndicator} />
        </span>
      ) : (
        <TerminalSquare className="size-3 shrink-0" />
      )}

      {isRenaming ? (
        <input
          type="text"
          value={renameValue}
          autoFocus
          data-tab-rename-input="true"
          onClick={(event) => event.stopPropagation()}
          onPointerDown={stopPointer}
          onChange={(event) => onRenameValueChange(event.target.value)}
          onBlur={() => onCommitRename(tab.id)}
          onKeyDown={(event) => {
            event.stopPropagation();
            if (event.key === "Enter") {
              event.preventDefault();
              event.currentTarget.blur();
            } else if (event.key === "Escape") {
              event.preventDefault();
              onCancelRename();
              event.currentTarget.blur();
            }
          }}
          className="min-w-0 flex-1 rounded border border-ring bg-background px-1 py-0.5 text-xs text-foreground outline-none"
        />
      ) : (
        <span className="min-w-0 flex-1 truncate text-left">{tab.label}</span>
      )}

      {isPinned ? <Pin className="size-2.5 shrink-0 text-muted-foreground/80" aria-label="Pinned tab" /> : null}

      {!isPinned ? (
        <span
          role="button"
          tabIndex={0}
          aria-label={`Close ${tab.label}`}
          onPointerDown={stopPointer}
          onClick={(event) => {
            event.stopPropagation();
            onClose(tab.id);
          }}
          onKeyDown={(event) => {
            if (event.key === "Enter" || event.key === " ") {
              event.preventDefault();
              event.stopPropagation();
              onClose(tab.id);
            }
          }}
          className="no-drag rounded p-0.5 text-muted-foreground opacity-0 hover:bg-muted hover:text-foreground group-hover:opacity-100 focus:opacity-100"
        >
          <X className="size-3" />
        </span>
      ) : null}

      {active ? (
        <span data-testid="tab-active-indicator" className="pointer-events-none absolute inset-x-0 bottom-0 h-px bg-foreground" />
      ) : null}
    </div>
  );
});

import type { PaneDirection } from "../../state/paneTree";

export type TabDropEdge = "left" | "right" | "top" | "bottom";

export type TabDragData = {
  type: "tab";
  tabId: string;
  groupId: string;
  index: number;
};

export type PaneDragData = {
  type: "pane";
  tabId: string;
  sourcePaneId?: string;
  sourceSessionId?: string;
  leafId?: string;
};

export type GroupBodyDropData = {
  type: "group-body";
  groupId: string;
};

export type GroupEdgeDropData = {
  type: "group-edge";
  groupId: string;
  edge: TabDropEdge;
};

export type PaneLeafDropData = {
  type: "pane-leaf";
  tabId: string;
  leafId: string;
};

export type PaneEdgeDropData = {
  type: "pane-edge";
  tabId: string;
  leafId: string;
  edge: TabDropEdge;
};

export type WorkspaceDragData = TabDragData | PaneDragData;
export type WorkspaceDropData = TabDragData | GroupBodyDropData | GroupEdgeDropData | PaneLeafDropData | PaneEdgeDropData;

export type WorkspaceDropCommand =
  | {
      type: "move-tab-to-group";
      tabId: string;
      targetGroupId: string;
      targetIndex?: number;
    }
  | {
      type: "move-tab-to-split";
      tabId: string;
      targetGroupId: string;
      direction: PaneDirection;
      position: "first" | "second";
    }
  | {
      type: "move-tab-to-pane-split";
      sourceTabId: string;
      targetTabId: string;
      targetLeafId: string;
      direction: PaneDirection;
      position: "first" | "second";
    }
  | {
      type: "move-pane-to-pane-split";
      sourceTabId: string;
      sourceLeafId: string;
      targetTabId: string;
      targetLeafId: string;
      direction: PaneDirection;
      position: "first" | "second";
    }
  | {
      type: "detach-pane-to-tab";
      sourceTabId: string;
      leafId: string;
      targetGroupId: string;
      targetIndex?: number;
    }
  | {
      type: "swap-panes";
      tabId: string;
      sourceLeafId: string;
      targetLeafId: string;
    };

export function isWorkspaceDragData(value: unknown): value is WorkspaceDragData {
  if (!value || typeof value !== "object") return false;
  if (!("type" in value)) return false;
  const type = value.type;
  if (type === "tab") {
    return (
      "tabId" in value &&
      typeof value.tabId === "string" &&
      "groupId" in value &&
      typeof value.groupId === "string" &&
      "index" in value &&
      typeof value.index === "number"
    );
  }
  if (type === "pane") {
    return (
      "tabId" in value &&
      typeof value.tabId === "string" &&
      (("sourcePaneId" in value && typeof value.sourcePaneId === "string") ||
        ("leafId" in value && typeof value.leafId === "string"))
    );
  }
  return false;
}

export function isWorkspaceDropData(value: unknown): value is WorkspaceDropData {
  if (!value || typeof value !== "object") return false;
  if (!("type" in value)) return false;
  const type = value.type;
  switch (type) {
    case "tab":
      return (
        "tabId" in value &&
        typeof value.tabId === "string" &&
        "groupId" in value &&
        typeof value.groupId === "string" &&
        "index" in value &&
        typeof value.index === "number"
      );
    case "group-body":
      return "groupId" in value && typeof value.groupId === "string";
    case "group-edge":
      return "groupId" in value && typeof value.groupId === "string" && "edge" in value && isTabDropEdge(value.edge);
    case "pane-leaf":
      return "tabId" in value && typeof value.tabId === "string" && "leafId" in value && typeof value.leafId === "string";
    case "pane-edge":
      return (
        "tabId" in value &&
        typeof value.tabId === "string" &&
        "leafId" in value &&
        typeof value.leafId === "string" &&
        "edge" in value &&
        isTabDropEdge(value.edge)
      );
    default:
      return false;
  }
}

export function resolveWorkspaceDropCommand(
  active: WorkspaceDragData,
  over: WorkspaceDropData | null,
): WorkspaceDropCommand | null {
  if (!over) return null;

  if (active.type === "tab") {
    switch (over.type) {
      case "pane-edge": {
        const { direction, position } = edgeToSplit(over.edge);
        return {
          type: "move-tab-to-pane-split",
          sourceTabId: active.tabId,
          targetTabId: over.tabId,
          targetLeafId: over.leafId,
          direction,
          position,
        };
      }
      case "group-edge": {
        const { direction, position } = edgeToSplit(over.edge);
        return {
          type: "move-tab-to-split",
          tabId: active.tabId,
          targetGroupId: over.groupId,
          direction,
          position,
        };
      }
      case "tab":
        if (over.tabId === active.tabId && over.groupId === active.groupId) return null;
        return {
          type: "move-tab-to-group",
          tabId: active.tabId,
          targetGroupId: over.groupId,
          targetIndex: over.index,
        };
      case "group-body":
        return {
          type: "move-tab-to-group",
          tabId: active.tabId,
          targetGroupId: over.groupId,
        };
      case "pane-leaf":
        return null;
    }
  }

  if (active.type === "pane") {
    const sourceLeafId = active.sourcePaneId ?? active.leafId ?? "";
    switch (over.type) {
      case "pane-edge": {
        if (over.tabId === active.tabId && over.leafId === sourceLeafId) return null;
        const { direction, position } = edgeToSplit(over.edge);
        return {
          type: "move-pane-to-pane-split",
          sourceTabId: active.tabId,
          sourceLeafId,
          targetTabId: over.tabId,
          targetLeafId: over.leafId,
          direction,
          position,
        };
      }
      case "tab":
        return {
          type: "detach-pane-to-tab",
          sourceTabId: active.tabId,
          leafId: sourceLeafId,
          targetGroupId: over.groupId,
          targetIndex: over.index + 1,
        };
      case "group-body":
        return {
          type: "detach-pane-to-tab",
          sourceTabId: active.tabId,
          leafId: sourceLeafId,
          targetGroupId: over.groupId,
        };
      case "pane-leaf":
        if (over.tabId !== active.tabId || over.leafId === sourceLeafId) return null;
        return {
          type: "swap-panes",
          tabId: active.tabId,
          sourceLeafId,
          targetLeafId: over.leafId,
        };
      case "group-edge":
        return null;
    }
  }

  return null;
}

export function dropPriority(active: WorkspaceDragData, over: WorkspaceDropData): number {
  if (active.type === "tab") {
    if (over.type === "pane-edge") return over.edge === "left" || over.edge === "right" ? 0 : 1;
    if (over.type === "group-edge") return over.edge === "left" || over.edge === "right" ? 2 : 3;
    if (over.type === "tab") return 4;
    if (over.type === "group-body") return 5;
    return 100;
  }

  if (over.type === "pane-edge") return over.edge === "left" || over.edge === "right" ? 0 : 1;
  if (over.type === "tab") return 2;
  if (over.type === "group-body") return 3;
  if (over.type === "pane-leaf") return 4;
  return 100;
}

export function edgeToSplit(edge: TabDropEdge): { direction: PaneDirection; position: "first" | "second" } {
  if (edge === "left") return { direction: "horizontal", position: "first" };
  if (edge === "right") return { direction: "horizontal", position: "second" };
  if (edge === "top") return { direction: "vertical", position: "first" };
  return { direction: "vertical", position: "second" };
}

function isTabDropEdge(value: unknown): value is TabDropEdge {
  return value === "left" || value === "right" || value === "top" || value === "bottom";
}

import { useRef, useEffect } from "react";
import { setBrowserBounds, setBrowserVisible } from "../lib/browserTauri";
import { BrowserToolbar } from "./BrowserToolbar";
import type { BrowserTab } from "../lib/types";

interface BrowserPaneProps {
  tab: BrowserTab;
  visible?: boolean;
  onNavigate: (url: string) => void;
  onReload: () => void;
}

export function BrowserPane({ tab, visible = true, onNavigate, onReload }: BrowserPaneProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    const updateVisibility = (nextVisible: boolean) => {
      void setBrowserVisible(tab.browserId, nextVisible).catch(() => undefined);
    };

    const updateBounds = () => {
      if (!visible) {
        updateVisibility(false);
        return;
      }

      const rect = el.getBoundingClientRect();
      void setBrowserBounds(tab.browserId, {
        x: rect.x,
        y: rect.y,
        width: rect.width,
        height: rect.height,
      }).catch(() => undefined);
      updateVisibility(true);
    };

    updateBounds();

    const resizeObserver = new ResizeObserver(() => {
      updateBounds();
    });

    resizeObserver.observe(el);
    window.addEventListener("resize", updateBounds);

    return () => {
      resizeObserver.disconnect();
      window.removeEventListener("resize", updateBounds);
      // Native child webviews outlive React DOM nodes; cleanup also covers Fast Refresh remounts.
      updateVisibility(false);
    };
  }, [tab.browserId, visible]);

  return (
    <div className="flex flex-col w-full h-full bg-background overflow-hidden">
      <BrowserToolbar tab={tab} onNavigate={onNavigate} onReload={onReload} />
      <div
        ref={containerRef}
        data-testid="browser-viewport"
        className="flex-1 w-full bg-card relative"
      />
    </div>
  );
}

import { invoke } from "@tauri-apps/api/core";
import type {
  BrowserSessionSummary,
