    62	export const workspaceCollisionDetection: CollisionDetection = (args) => {
    63	  const activeData = args.active.data.current;
    64	  if (!isWorkspaceDragData(activeData)) return pointerWithin(args);
    65	  const containerDataById = new Map<UniqueIdentifier, unknown>();
    66	  for (const container of args.droppableContainers) {
    67	    containerDataById.set(container.id, container.data.current);
    68	  }
    69	  return pointerWithin(args)
    70	    .filter((collision) => {
    71	      const data = containerDataById.get(collision.id);
    72	      return isWorkspaceDropData(data) && dropPriority(activeData, data) < 100;
    73	    })
    74	    .sort((left, right) => {
    75	      const leftData = containerDataById.get(left.id);
    76	      const rightData = containerDataById.get(right.id);
    77	      if (!isWorkspaceDropData(leftData) || !isWorkspaceDropData(rightData)) return 0;
    78	      return dropPriority(activeData, leftData) - dropPriority(activeData, rightData);
    79	    });
